def rotate_90_ccw(grid):
    """Rotate grid 90 degrees counter-clockwise"""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            result[cols - 1 - c][r] = grid[r][c]
    return result

